def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: dict[str, bool] = {}
    rejected: list[int] = []
    undo_stack: list[tuple] = []

    def valid_amount(s: str) -> bool:
        return len(s) > 0 and all('0' <= c <= '9' for c in s)

    for i, op in enumerate(ops):
        parts = op.split()
        verb = parts[0] if parts else ""
        ok = True
        undo_rec = None

        if verb == "undo":
            if len(parts) != 1 or not undo_stack:
                ok = False
            else:
                rec = undo_stack.pop()
                kind = rec[0]
                if kind == "open":
                    del balances[rec[1]]
                    del frozen[rec[1]]
                elif kind == "deposit":
                    balances[rec[1]] -= rec[2]
                elif kind == "withdraw":
                    balances[rec[1]] += rec[2]
                elif kind == "transfer":
                    balances[rec[1]] += rec[2]
                    balances[rec[3]] -= rec[2]
                elif kind == "freeze":
                    frozen[rec[1]] = rec[2]
                elif kind == "unfreeze":
                    frozen[rec[1]] = rec[2]
                undo_rec = "no_push"

        elif verb == "open":
            if len(parts) != 3 or not valid_amount(parts[2]):
                ok = False
            else:
                a, n = parts[1], int(parts[2])
                if a in balances:
                    ok = False
                else:
                    balances[a] = n
                    frozen[a] = False
                    undo_rec = ("open", a)

        elif verb == "deposit":
            if len(parts) != 3 or not valid_amount(parts[2]):
                ok = False
            else:
                a, n = parts[1], int(parts[2])
                if n <= 0 or a not in balances:
                    ok = False
                else:
                    balances[a] += n
                    undo_rec = ("deposit", a, n)

        elif verb == "withdraw":
            if len(parts) != 3 or not valid_amount(parts[2]):
                ok = False
            else:
                a, n = parts[1], int(parts[2])
                if n <= 0 or a not in balances or frozen[a] or balances[a] < n:
                    ok = False
                else:
                    balances[a] -= n
                    undo_rec = ("withdraw", a, n)

        elif verb == "transfer":
            if len(parts) != 4 or not valid_amount(parts[3]):
                ok = False
            else:
                a, b, n = parts[1], parts[2], int(parts[3])
                if (n <= 0 or a == b or a not in balances or b not in balances
                        or frozen[a] or balances[a] < n):
                    ok = False
                else:
                    balances[a] -= n
                    balances[b] += n
                    undo_rec = ("transfer", a, n, b)

        elif verb == "freeze":
            if len(parts) != 2:
                ok = False
            else:
                a = parts[1]
                if a not in balances or frozen[a]:
                    ok = False
                else:
                    frozen[a] = True
                    undo_rec = ("freeze", a, False)

        elif verb == "unfreeze":
            if len(parts) != 2:
                ok = False
            else:
                a = parts[1]
                if a not in balances or not frozen[a]:
                    ok = False
                else:
                    frozen[a] = False
                    undo_rec = ("unfreeze", a, True)

        else:
            ok = False

        if not ok:
            rejected.append(i)
        elif undo_rec != "no_push" and undo_rec is not None:
            undo_stack.append(undo_rec)

    return balances, rejected
